# ---------------- DATABASE ----------------
def get_connection():
    return sqlite3.connect(DB_NAME)

def hash_password(password):
    return hashlib.sha256(password.encode("utf-8")).hexdigest()

def init_db():
    with get_connection() as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                username TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                role TEXT NOT NULL CHECK(role IN ('client', 'caterer'))
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS bookings (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                client_id INTEGER NOT NULL,
                customer TEXT NOT NULL,
                mobile TEXT NOT NULL,
                event_type TEXT NOT NULL,
                event_date TEXT NOT NULL,
                venue TEXT NOT NULL,
                guests INTEGER NOT NULL,
                menu TEXT NOT NULL,
                cost REAL NOT NULL,
                status TEXT NOT NULL DEFAULT 'Pending',
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY(client_id) REFERENCES users(id)
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS inventory (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                item TEXT NOT NULL UNIQUE,
                quantity REAL NOT NULL,
                unit TEXT NOT NULL,
                price REAL NOT NULL,
                supplier TEXT
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS suppliers (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                mobile TEXT NOT NULL,
                item TEXT NOT NULL
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS transactions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                booking_id INTEGER NOT NULL,
                client_id INTEGER NOT NULL,
                amount REAL NOT NULL,
                paid REAL NOT NULL DEFAULT 0,
                expense REAL NOT NULL DEFAULT 0,
                payment_date TEXT NOT NULL,
                FOREIGN KEY(booking_id) REFERENCES bookings(id),
                FOREIGN KEY(client_id) REFERENCES users(id)
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS food_waste (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_name TEXT NOT NULL,
                leftover REAL NOT NULL,
                wasted REAL NOT NULL,
                waste_date TEXT NOT NULL
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS catering_packages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                package_name TEXT NOT NULL UNIQUE,
                rate_per_guest REAL NOT NULL CHECK(rate_per_guest >= 0),
                description TEXT DEFAULT ''
            )
        """)

def create_initial_caterer():
    # Demo credentials. Set CATERER_USERNAME/CATERER_PASSWORD environment variables to customize.
    import os
    username = os.getenv("CATERER_USERNAME", "admin")
    password = os.getenv("CATERER_PASSWORD", "Ashirvad@2026")
    with get_connection() as conn:
        row = conn.execute(
            "SELECT id FROM users WHERE username = ? AND role = 'caterer'",
            (username,)
        ).fetchone()
        if row:
            # Keep the demo admin password in sync when upgrading this project.
            conn.execute(
                "UPDATE users SET password_hash = ? WHERE id = ?",
                (hash_password(password), row[0])
            )
        else:
            conn.execute(
                "INSERT INTO users (name, username, password_hash, role) VALUES (?, ?, ?, 'caterer')",
                ("Ashirvad Caterer", username, hash_password(password))
            )


def migrate_db():
    """Add columns expected by this version when an older catering.db already exists."""
    with get_connection() as conn:
        migrations = {
            "bookings": {
                "client_id": "INTEGER",
                "customer": "TEXT",
                "mobile": "TEXT",
                "event_type": "TEXT",
                "event_date": "TEXT",
                "venue": "TEXT",
                "guests": "INTEGER DEFAULT 1",
                "menu": "TEXT DEFAULT ''",
                "cost": "REAL DEFAULT 0",
                "status": "TEXT DEFAULT 'Pending'",
                "created_at": "TEXT"
            },
            "transactions": {
                "booking_id": "INTEGER",
                "client_id": "INTEGER",
                "amount": "REAL DEFAULT 0",
                "paid": "REAL DEFAULT 0",
                "expense": "REAL DEFAULT 0",
                "payment_date": "TEXT"
            }
        }
        for table, columns in migrations.items():
            existing = {row[1] for row in conn.execute(f"PRAGMA table_info({table})")}
            for column, definition in columns.items():
                if column not in existing:
                    conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} {definition}")

init_db()
migrate_db()
create_initial_caterer()

MENU_CATEGORIES = {
    "Welcome Drinks": ["Lemon Juice", "Mango Juice", "Buttermilk", "Soft Drinks", "Welcome Mocktail"],
    "Starters": ["Paneer Tikka", "Veg Manchurian", "Hara Bhara Kabab", "Samosa"],
    "Main Course": ["Paneer Masala", "Mix Veg", "Dal Tadka", "Chole"],
    "Rice": ["Jeera Rice", "Veg Pulao", "Biryani", "Plain Rice"],
    "Breads": ["Chapati", "Butter Naan", "Puri", "Tandoori Roti"],
    "Desserts": ["Gulab Jamun", "Ice Cream", "Shrikhand", "Jalebi"]
}

def query_all(sql, params=()):
    with get_connection() as conn:
        return conn.execute(sql, params).fetchall()

def execute(sql, params=()):
    with get_connection() as conn:
        cur = conn.execute(sql, params)
        return cur.lastrowid, cur.rowcount

def show_login():
    st.title("🍽️ Smart Catering Management System")
    st.subheader("Ashirvad Ketering Service")
    login_tab, register_tab = st.tabs(["Login", "Client Registration"])

    with login_tab:
        st.markdown("### Select your login type")
        login_role_label = st.radio(
            "Who is logging in?",
            ["👨‍🍳 Caterer / Admin", "👤 Client"],
            horizontal=True,
            key="login_role_choice"
        )
        selected_role = "caterer" if login_role_label == "👨‍🍳 Caterer / Admin" else "client"
        st.caption(
            "Admin login: manage bookings, food/inventory, suppliers, payments and reports."
            if selected_role == "caterer"
            else "Client login: create bookings and view only your own bookings and payments."
        )
        username = st.text_input("Username", key="login_username")
        password = st.text_input("Password", type="password", key="login_password")
        if st.button("Login as " + ("Caterer / Admin" if selected_role == "caterer" else "Client"), type="primary"):
            row = query_all(
                "SELECT id, name, username, password_hash, role FROM users WHERE username = ? AND role = ?",
                (username.strip(), selected_role)
            )
            if row and hmac.compare_digest(row[0][3], hash_password(password)):
                st.session_state.user = {
                    "id": row[0][0],
                    "name": row[0][1],
                    "username": row[0][2],
                    "role": row[0][4]
                }
                st.rerun()
            else:
                st.error("Invalid username/password for the selected login type.")

    with register_tab:
        st.markdown("### Create a Client Account")
        st.caption("Registration is for clients only. Caterer access is created separately.")
        name = st.text_input("Full Name", key="reg_name")
        username = st.text_input("Choose Username", key="reg_username")
        password = st.text_input("Create Password", type="password", key="reg_password")
        confirm = st.text_input("Confirm Password", type="password", key="reg_confirm")
        if st.button("Register Client"):
            if not name.strip() or not username.strip() or not password:
                st.error("Please fill all fields.")
            elif len(password) < 8:
                st.error("Password must contain at least 8 characters.")
            elif password != confirm:
                st.error("Passwords do not match.")
            else:
                try:
                    execute(
                        "INSERT INTO users (name, username, password_hash, role) VALUES (?, ?, ?, 'client')",
                        (name.strip(), username.strip(), hash_password(password))
                    )
                    st.success("Registration successful! Please login.")
                except sqlite3.IntegrityError:
                    st.error("This username already exists. Choose another one.")

def client_page(user):
    st.title("👤 Client Dashboard")
    st.write(f"Welcome, **{user['name']}**!")
    page = st.sidebar.radio(
        "Client Menu",
        ["Dashboard", "Book Catering", "My Bookings", "My Payments"]
    )

    if page == "Dashboard":
        total = query_all("SELECT COUNT(*) FROM bookings WHERE client_id=?", (user["id"],))[0][0]
        upcoming = query_all(
            "SELECT COUNT(*) FROM bookings WHERE client_id=? AND event_date>=?",
            (user["id"], date.today().isoformat())
        )[0][0]
        a, b = st.columns(2)
        a.metric("My Bookings", total)
        b.metric("Upcoming Events", upcoming)
        st.info("Use 'Book Catering' to request catering for your event.")

    elif page == "Book Catering":
        st.header("📅 Book Catering")
        with st.form("client_booking_form"):
            mobile = st.text_input("Mobile Number")
            event_type = st.selectbox("Event Type", ["Wedding", "Birthday", "Engagement", "Corporate", "Other"])
            event_date = st.date_input("Event Date", min_value=date.today())
            venue = st.text_input("Event Venue")
            guests = st.number_input("Number of Guests", min_value=1, value=100, step=1)

            selected_menu = []
            st.subheader("🍽️ Customize Your Menu")
            for category, items in MENU_CATEGORIES.items():
                selected = st.multiselect(category, items, key=f"client_{user['id']}_{category}")
                selected_menu.extend(selected)

            available_packages = query_all(
                "SELECT id, package_name, rate_per_guest, description FROM catering_packages ORDER BY package_name"
            )
            if available_packages:
                package_options = {
                    f"{row[1]} — ₹{float(row[2]):,.2f}/guest": row
                    for row in available_packages
                }
                selected_package_label = st.selectbox("Select Catering Package", list(package_options.keys()))
                selected_package = package_options[selected_package_label]
                rate = float(selected_package[2])
                if selected_package[3]:
                    st.caption(selected_package[3])
                st.caption(f"Rate set by caterer: ₹{rate:,.2f} per guest")
                total_cost = int(guests) * rate
                st.info(f"Estimated total for {int(guests)} guests: ₹{total_cost:,.2f}")
            else:
                selected_package = None
                rate = 0.0
                total_cost = 0.0
                st.warning("Catering packages and rates have not been added by the caterer yet. Please try again later.")
            submit = st.form_submit_button("Submit Booking Request", type="primary")

            if submit:
                if not mobile.isdigit() or len(mobile) != 10:
                    st.error("Enter a valid 10-digit mobile number.")
                elif not venue.strip():
                    st.error("Enter the event venue.")
                elif not selected_menu:
                    st.error("Select at least one food item.")
                elif not available_packages or selected_package is None:
                    st.error("The caterer has not configured package rates yet. Please contact the caterer.")
                else:
                    execute("""
                        INSERT INTO bookings
                        (client_id, customer, mobile, event_type, event_date, venue, guests, menu, cost)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """, (user["id"], user["name"], mobile, event_type, event_date.isoformat(),
                          venue.strip(), int(guests), ", ".join(selected_menu), float(total_cost)))
                    st.success("Booking request submitted! You can track it under My Bookings.")

    elif page == "My Bookings":
        st.header("📋 My Bookings")
        rows = query_all("""
            SELECT id, event_type, event_date, venue, guests, menu, cost, status
            FROM bookings WHERE client_id=? ORDER BY id DESC
        """, (user["id"],))
        if rows:
            st.table([
                {"Booking ID": r[0], "Event": r[1], "Date": r[2], "Venue": r[3],
                 "Guests": r[4], "Menu": r[5], "Estimated Cost (₹)": r[6], "Status": r[7]}
                for r in rows
            ])
        else:
            st.info("You have not made any bookings yet.")

    elif page == "My Payments":
        st.header("💳 My Payments")
        rows = query_all("""
            SELECT t.booking_id, b.event_type, t.amount, t.paid, t.payment_date
            FROM transactions t JOIN bookings b ON b.id=t.booking_id
            WHERE t.client_id=? ORDER BY t.id DESC
        """, (user["id"],))
        if rows:
            st.table([
                {"Booking ID": r[0], "Event": r[1], "Booking Value (₹)": r[2],
                 "Paid (₹)": r[3], "Record Date": r[4]}
                for r in rows
            ])
        else:
            st.info("No payment records yet. The caterer records payments.")

def caterer_page(user):
    st.title("👨‍🍳 Caterer Dashboard")
    st.write(f"Welcome, **{user['name']}** — Ashirvad Ketering Service")

    page = st.sidebar.radio(
        "Caterer Menu",
        ["Dashboard", "1. Booking Management", "2. Food & Inventory Management",
         "3. Payments & Reports"]
    )

    if page == "Dashboard":
        bookings = query_all("SELECT COUNT(*) FROM bookings")[0][0]
        upcoming = query_all(
            "SELECT COUNT(*) FROM bookings WHERE event_date>=?",
            (date.today().isoformat(),)
        )[0][0]
        # Current stock alert threshold: 5 units (based on the unit entered in inventory).
        low_items = query_all(
            "SELECT item, quantity, unit, price, supplier FROM inventory WHERE quantity<=5 ORDER BY quantity ASC, item"
        )
        low = len(low_items)
        c1, c2, c3 = st.columns(3)
        c1.metric("All Bookings", bookings)
        c2.metric("Upcoming Events", upcoming)
        c3.metric("Low Stock Items", low)
        st.info("Use the three main modules to manage bookings, food/inventory, and payments/reports.")

        # Booking-wise ingredient alerts: show which event/menu is affected by low stock.
        # These are starter mappings; adjust them to match the caterer's actual recipes.
        INGREDIENT_MENU_MAP = {
            "lemon": ["Lemon Juice"],
            "lemon juice": ["Lemon Juice"],
            "buttermilk": ["Buttermilk"],
            "paneer": ["Paneer Masala", "Paneer Tikka"],
            "onion": ["Paneer Masala", "Veg Manchurian", "Dal Tadka", "Biryani", "Samosa"],
            "tomato": ["Paneer Masala", "Dal Tadka", "Mix Veg", "Biryani"],
            "rice": ["Jeera Rice", "Veg Pulao", "Biryani", "Plain Rice"],
            "jeera": ["Jeera Rice"],
            "potato": ["Samosa", "Hara Bhara Kabab"],
            "maida": ["Samosa", "Butter Naan", "Puri"],
            "oil": ["Veg Manchurian", "Samosa", "Paneer Tikka", "Biryani"],
            "dal": ["Dal Tadka"],
            "wheat flour": ["Chapati", "Puri"],
            "atta": ["Chapati", "Puri"],
            "cream": ["Paneer Masala"],
            "vegetables": ["Mix Veg", "Veg Manchurian", "Veg Pulao"],
            "milk": ["Shrikhand", "Ice Cream"],
            "sugar": ["Lemon Juice", "Gulab Jamun", "Shrikhand", "Jalebi"],
        }

        active_bookings = query_all("""
            SELECT id, customer, event_type, event_date, guests, menu, status
            FROM bookings
            WHERE COALESCE(status, 'Pending') != 'Cancelled'
            ORDER BY event_date ASC, id DESC
        """)

        st.subheader("⚠️ Booking-wise Ingredient Alerts")
        if not low_items:
            st.success("No low-stock ingredients. All items are above the low-stock threshold.")
        else:
            impact_rows = []
            for ingredient, quantity, unit, price, supplier in low_items:
                ingredient_name = str(ingredient).strip()
                ingredient_key = ingredient_name.casefold().strip()
                affected_menu_names = INGREDIENT_MENU_MAP.get(ingredient_key, [])
                # Flexible aliases for common ingredient names entered by the caterer.
                aliases = {
                    "rice": ["Jeera Rice", "Veg Pulao", "Biryani", "Plain Rice"],
                    "basmati rice": ["Jeera Rice", "Veg Pulao", "Biryani", "Plain Rice"],
                    "sugar": ["Lemon Juice", "Gulab Jamun", "Shrikhand", "Jalebi", "Ice Cream"],
                    "onions": INGREDIENT_MENU_MAP["onion"],
                    "tomatoes": INGREDIENT_MENU_MAP["tomato"],
                    "potatoes": INGREDIENT_MENU_MAP["potato"],
                    "wheat": ["Chapati", "Puri", "Tandoori Roti"],
                    "flour": ["Chapati", "Puri", "Samosa", "Butter Naan", "Tandoori Roti"],
                    "cooking oil": INGREDIENT_MENU_MAP["oil"],
                    "vegetable oil": INGREDIENT_MENU_MAP["oil"],
                }
                if not affected_menu_names:
                    affected_menu_names = aliases.get(ingredient_key, [])
                # Match case-insensitively and tolerate extra spaces in older booking records.
                affected_keys = {" ".join(x.casefold().split()) for x in affected_menu_names}
                stock_status = "OUT OF STOCK" if float(quantity) <= 0 else "LOW STOCK"

                for booking in active_bookings:
                    booking_menu = [" ".join(x.casefold().split()) for x in (booking[5] or "").split(",") if x.strip()]
                    matched_menu = [menu_item for menu_item in booking_menu if menu_item in affected_keys]
                    if matched_menu:
                        event_name = str(booking[2] or "Event").strip()
                        for menu_item in matched_menu:
                            impact_rows.append({
                                "Booking Alert": f"{event_name} — {ingredient_name}: {stock_status}",
                                "Booking ID": f"#{booking[0]}",
                                "Customer": booking[1] or "Client",
                                "Event Date": booking[3] or "—",
                                "Menu Item Affected": menu_item,
                                "Ingredient": ingredient_name,
                                "Stock Status": stock_status,
                                "Available Stock": f"{float(quantity):g} {unit}",
                                "Guests": booking[4] or 0,
                            })

            if impact_rows:
                st.warning(
                    "Each row identifies the event booking affected by a low-stock ingredient. "
                    "Example: Birthday — Rice: OUT OF STOCK."
                )
                st.dataframe(impact_rows, hide_index=True, use_container_width=True)
            else:
                st.info(
                    "Low-stock ingredients are listed in Food & Inventory Management. "
                    "No booking match was found using the current ingredient-to-menu mapping. "
                    "For example, Rice is mapped to Jeera Rice, Veg Pulao, Biryani and Plain Rice. "
                    "Edit INGREDIENT_MENU_MAP if your actual recipes differ."
                )

        st.caption(f"Database file: {DB_NAME}")

    elif page == "1. Booking Management":
        st.header("📋 Manage All Client Bookings")
        # Read directly from bookings so missing/old user links cannot hide a booking.
        # The database path is anchored to this app.py file to avoid opening a second DB.
        rows = query_all("""
            SELECT b.id,
                   COALESCE((SELECT u.name FROM users u WHERE u.id = b.client_id), b.customer, 'Client details unavailable') AS client_name,
                   b.mobile, b.event_type, b.event_date, b.venue,
                   b.guests, b.menu, b.cost, COALESCE(b.status, 'Pending')
            FROM bookings b
            ORDER BY b.id DESC
        """)
        st.caption(f"Bookings found: {len(rows)}")
        if rows:
            st.table([
                {"Booking ID": r[0], "Client": r[1] or "Client details unavailable", "Mobile": r[2] or "—", "Event": r[3] or "—",
                 "Date": r[4] or "—", "Venue": r[5] or "—", "Guests": r[6] or 0, "Menu": r[7] or "—",
                 "Estimated Cost (₹)": r[8] or 0, "Status": r[9]}
                for r in rows
            ])

            st.subheader("Update Booking Status")
            booking_ids = [r[0] for r in rows]
            booking_id = st.selectbox("Select Booking ID", booking_ids)
            new_status = st.selectbox("New Status", ["Pending", "Confirmed", "Completed", "Cancelled"])
            if st.button("Update Status"):
                execute("UPDATE bookings SET status=? WHERE id=?", (new_status, booking_id))
                st.success("Booking status updated.")
                st.rerun()
        else:
            st.info("No client bookings yet.")

        st.divider()
        st.subheader("💵 Catering Package & Rate Settings")
        st.caption("Only the caterer sets these rates. Clients see the saved rates and the total is calculated automatically.")
        with st.form("package_rate_form", clear_on_submit=True):
            package_name = st.text_input("Package Name", placeholder="e.g. Standard Veg Menu")
            package_rate = st.number_input("Rate Per Guest (₹)", min_value=0.0, value=0.0, step=25.0)
            package_description = st.text_input("Package Description (optional)", placeholder="e.g. Starters, main course, rice, breads and dessert")
            save_package = st.form_submit_button("Save Package Rate")
            if save_package:
                if not package_name.strip():
                    st.error("Enter a package name.")
                elif package_rate <= 0:
                    st.error("Rate per guest must be greater than zero.")
                else:
                    try:
                        execute(
                            "INSERT INTO catering_packages(package_name, rate_per_guest, description) VALUES(?,?,?)",
                            (package_name.strip(), float(package_rate), package_description.strip())
                        )
                        st.success("Package rate saved. Clients can now select this package.")
                        st.rerun()
                    except sqlite3.IntegrityError:
                        execute(
                            "UPDATE catering_packages SET rate_per_guest=?, description=? WHERE LOWER(package_name)=LOWER(?)",
                            (float(package_rate), package_description.strip(), package_name.strip())
                        )
                        st.success("Existing package rate updated.")
                        st.rerun()

        package_rows = query_all("SELECT id, package_name, rate_per_guest, description FROM catering_packages ORDER BY package_name")
        if package_rows:
            st.dataframe([
                {"Package": r[1], "Rate Per Guest (₹)": f"₹{float(r[2]):,.2f}", "Description": r[3] or "—"}
                for r in package_rows
            ], hide_index=True, use_container_width=True)
            package_to_delete = st.selectbox(
                "Select package to remove",
                [r[0] for r in package_rows],
                format_func=lambda pid: next(f"{r[1]} — ₹{float(r[2]):,.2f}/guest" for r in package_rows if r[0] == pid),
                key="delete_package_select"
            )
            if st.button("Remove Selected Package"):
                execute("DELETE FROM catering_packages WHERE id=?", (package_to_delete,))
                st.success("Package removed.")
                st.rerun()
        else:
            st.info("No packages configured yet. Add the caterer's actual package rates above.")

    elif page == "2. Food & Inventory Management":
        st.header("🥗 Food & Inventory")
        st.caption("Add the ingredients purchased for monthly stock. If an ingredient already exists, its new purchase quantity will be added to the current stock.")
        with st.form("inventory_form"):
            item = st.text_input("Ingredient Name")
            quantity = st.number_input("Quantity Purchased / Added", min_value=0.0)
            unit = st.selectbox("Unit", ["kg", "litre", "packet", "piece"])
            price = st.number_input("Price per Unit (₹)", min_value=0.0)
            supplier = st.text_input("Supplier Name")
            save = st.form_submit_button("Add to Inventory")
            if save:
                if not item.strip():
                    st.error("Enter ingredient name.")
                elif quantity <= 0:
                    st.error("Quantity must be greater than zero.")
                else:
                    existing = query_all(
                        "SELECT id, quantity, unit FROM inventory WHERE LOWER(item)=LOWER(?)",
                        (item.strip(),)
                    )
                    if existing:
                        existing_id, old_quantity, old_unit = existing[0]
                        if old_unit != unit:
                            st.error(
                                f"This ingredient is already stored in '{old_unit}'. "
                                f"Use the same unit so stock quantities can be added correctly."
                            )
                        else:
                            execute(
                                "UPDATE inventory SET quantity=?, price=?, supplier=? WHERE id=?",
                                (float(old_quantity) + float(quantity), price,
                                 supplier.strip(), existing_id)
                            )
                            st.success(
                                f"Added {quantity:g} {unit} to {item.strip()}. "
                                f"New total stock: {float(old_quantity) + float(quantity):g} {unit}."
                            )
                            st.rerun()
                    else:
                        execute(
                            "INSERT INTO inventory(item, quantity, unit, price, supplier) VALUES(?,?,?,?,?)",
                            (item.strip(), quantity, unit, price, supplier.strip())
                        )
                        st.success(f"{item.strip()} added to inventory.")
                        st.rerun()

        st.divider()

        rows = query_all("SELECT * FROM inventory ORDER BY item")
        st.subheader("Current Stock")
        if rows:
            st.table([
                {"ID": r[0], "Item / Ingredient": r[1], "Available Quantity": r[2], "Unit": r[3],
                 "Price per Unit (₹)": r[4], "Supplier": r[5],
                 "Stock Status": "Out of Stock" if r[2] <= 0 else ("Low Stock" if r[2] <= 5 else "In Stock")}
                for r in rows
            ])
            # Show low-stock/out-of-stock ingredients with the bookings whose menus use them.
            st.subheader("⚠️ Low Stock & Affected Events")
            low_inventory = [r for r in rows if float(r[2]) <= 5]
            inventory_bookings = query_all("""
                SELECT id, customer, event_type, event_date, menu, status
                FROM bookings
                WHERE COALESCE(status, 'Pending') != 'Cancelled'
                ORDER BY event_date ASC, id DESC
            """)
            inventory_map = {
                "lemon": ["Lemon Juice"], "lemon juice": ["Lemon Juice"],
                "buttermilk": ["Buttermilk"], "paneer": ["Paneer Masala", "Paneer Tikka"],
                "onion": ["Paneer Masala", "Veg Manchurian", "Dal Tadka", "Biryani", "Samosa"],
                "onions": ["Paneer Masala", "Veg Manchurian", "Dal Tadka", "Biryani", "Samosa"],
                "tomato": ["Paneer Masala", "Dal Tadka", "Mix Veg", "Biryani"],
                "tomatoes": ["Paneer Masala", "Dal Tadka", "Mix Veg", "Biryani"],
                "rice": ["Jeera Rice", "Veg Pulao", "Biryani", "Plain Rice"],
                "basmati rice": ["Jeera Rice", "Veg Pulao", "Biryani", "Plain Rice"],
                "jeera": ["Jeera Rice"], "potato": ["Samosa", "Hara Bhara Kabab"],
                "potatoes": ["Samosa", "Hara Bhara Kabab"],
                "maida": ["Samosa", "Butter Naan", "Puri"],
                "oil": ["Veg Manchurian", "Samosa", "Paneer Tikka", "Biryani"],
                "cooking oil": ["Veg Manchurian", "Samosa", "Paneer Tikka", "Biryani"],
                "dal": ["Dal Tadka"], "wheat flour": ["Chapati", "Puri"],
                "atta": ["Chapati", "Puri"], "flour": ["Chapati", "Puri", "Samosa", "Butter Naan", "Tandoori Roti"],
                "cream": ["Paneer Masala"], "vegetables": ["Mix Veg", "Veg Manchurian", "Veg Pulao"],
                "milk": ["Shrikhand", "Ice Cream"],
                "sugar": ["Lemon Juice", "Gulab Jamun", "Shrikhand", "Jalebi", "Ice Cream"],
            }
            inventory_alerts = []
            for stock_row in low_inventory:
                ingredient_name = str(stock_row[1]).strip()
                mapped_menu = inventory_map.get(ingredient_name.casefold(), [])
                for booking in inventory_bookings:
                    selected = [x.strip() for x in (booking[4] or "").split(",") if x.strip()]
                    for menu_item in selected:
                        if any(menu_item.casefold() == mapped.casefold() for mapped in mapped_menu):
                            qty = float(stock_row[2])
                            inventory_alerts.append({
                                "Alert": f"{booking[2] or 'Event'} — {ingredient_name}: {'OUT OF STOCK' if qty <= 0 else 'LOW STOCK'}",
                                "Booking ID": f"#{booking[0]}",
                                "Customer": booking[1] or "Client",
                                "Event Date": booking[3] or "—",
                                "Menu Item": menu_item,
                                "Ingredient": ingredient_name,
                                "Available Stock": f"{qty:g} {stock_row[3]}",
                            })
            if inventory_alerts:
                st.dataframe(inventory_alerts, hide_index=True, use_container_width=True)
            elif low_inventory:
                st.warning("Low/out-of-stock items are listed above, but no affected booking matched the current menu mapping. Check that ingredient names and selected menu items match the mapping.")
            else:
                st.success("No low-stock ingredients. All inventory items are above 5 units.")
            st.subheader("Update Stock Quantity")
            selected_id = st.selectbox("Select Item to Update", [r[0] for r in rows],
                                       format_func=lambda item_id: next(
                                           f"{r[1]} (current: {r[2]} {r[3]})" for r in rows if r[0] == item_id
                                       ))
            new_quantity = st.number_input("Enter New Quantity", min_value=0.0, key="caterer_new_stock")
            if st.button("Save Stock Update"):
                execute("UPDATE inventory SET quantity=? WHERE id=?", (new_quantity, selected_id))
                st.success("Stock quantity updated.")
                st.rerun()
        else:
            st.info("No stock items added yet. Add items above to start tracking inventory.")

        st.info(
            "Booking impact is shown on the Caterer Dashboard as a compact list: "
            "low ingredient → affected menu item → booking. Add ingredients here; "
            "the dashboard matches low-stock ingredients to active bookings."
        )

    elif page == "3. Payments & Reports":
        st.header("💰 Payments & Reports")
        finance_view = st.radio("Choose section", ["Payments & Expenses", "Business Reports"], horizontal=True)
        if finance_view == "Business Reports":
            page = "Reports"
        else:
            page = "Payments & Expenses"
        # The selected section is rendered below.
        bookings = query_all("SELECT id, client_id, customer, cost FROM bookings WHERE status!='Cancelled' ORDER BY id DESC")
        if bookings:
            options = {f"Booking #{r[0]} — {r[2]} (₹{r[3]:,.2f})": r for r in bookings}
            choice = st.selectbox("Select Booking", list(options.keys()))
            booking_id, client_id, customer, amount = options[choice]
            with st.form("payment_form"):
                paid = st.number_input("Payment Received (₹)", min_value=0.0, max_value=float(amount), value=0.0)
                expense = st.number_input("Event Expenses (₹)", min_value=0.0, value=0.0)
                record_date = st.date_input("Record Date", date.today())
                save = st.form_submit_button("Save Financial Record")
                if save:
                    execute("""INSERT INTO transactions(booking_id,client_id,amount,paid,expense,payment_date)
                               VALUES(?,?,?,?,?,?)""",
                            (booking_id, client_id, amount, paid, expense, record_date.isoformat()))
                    st.success("Financial record saved.")
        else:
            st.info("Create a booking before recording payments.")

        rows = query_all("""
            SELECT t.id,t.booking_id,u.name,t.amount,t.paid,t.expense,t.payment_date
            FROM transactions t JOIN users u ON u.id=t.client_id ORDER BY t.id DESC
        """)
        if rows:
            st.table([{"Record ID": r[0], "Booking ID": r[1], "Client": r[2],
                           "Booking Value (₹)": r[3], "Paid (₹)": r[4],
                           "Expense (₹)": r[5], "Date": r[6]} for r in rows],
                         use_container_width=True)

    elif page == "Food-Waste Management":
        st.header("♻️ Food-Waste Management")
        with st.form("waste_form"):
            event_name = st.text_input("Event Name")
            leftover = st.number_input("Leftover Food (kg)", min_value=0.0)
            wasted = st.number_input("Discarded Food (kg)", min_value=0.0)
            record_date = st.date_input("Event Date", date.today())
            save = st.form_submit_button("Save Food-Waste Record")
            if save:
                if not event_name.strip():
                    st.error("Enter event name.")
                elif wasted > leftover:
                    st.error("Discarded food cannot exceed leftover food.")
                else:
                    execute("INSERT INTO food_waste(event_name,leftover,wasted,waste_date) VALUES(?,?,?,?)",
                            (event_name.strip(), leftover, wasted, record_date.isoformat()))
                    st.success("Food-waste record saved.")

        rows = query_all("SELECT * FROM food_waste ORDER BY id DESC")
        if rows:
            st.table([{"ID": r[0], "Event": r[1], "Leftover (kg)": r[2],
                           "Wasted (kg)": r[3], "Date": r[4]} for r in rows],
                         use_container_width=True)

    if page == "Reports":
        st.header("📊 Business Reports")
        total = query_all("SELECT COUNT(*), COALESCE(SUM(cost),0) FROM bookings")[0]
        paid_exp = query_all("SELECT COALESCE(SUM(paid),0), COALESCE(SUM(expense),0) FROM transactions")[0]
        a, b, c = st.columns(3)
        a.metric("Total Bookings", total[0])
        b.metric("Booking Value (₹)", f"{total[1]:,.2f}")
        c.metric("Payments Received (₹)", f"{paid_exp[0]:,.2f}")
        a, b = st.columns(2)
        a.metric("Recorded Expenses (₹)", f"{paid_exp[1]:,.2f}")
        b.metric("Net Amount (₹)", f"{paid_exp[0] - paid_exp[1]:,.2f}")

# ---------------- APP ENTRY ----------------
if "user" not in st.session_state:
    show_login()
else:
    user = st.session_state.user
    # Embedded Ashirvad logo: works even if no separate image file is present
    import base64
    _ashirvad_logo_b64 = ""
    _ashirvad_logo_bytes = base64.b64decode(_ashirvad_logo_b64)
    st.sidebar.image(_ashirvad_logo_bytes, width=190)
    st.sidebar.markdown("---")
    st.sidebar.write(f"Signed in as **{user['name']}**")
    st.sidebar.caption(f"Role: {user['role'].title()}")
    if st.sidebar.button("Logout"):
        del st.session_state["user"]
        st.rerun()

    if user["role"] == "caterer":
        caterer_page(user)
    else:
        client_page(user)
